// Multi-source BFS on a grid, layer by layer. Returns the number of layers needed
// to reach every reachable target cell, or -1 if some target is unreachable.
int bfsLayers(vector<vector<int>>& g) {
    int n = g.size(), m = g[0].size();
    queue<pair<int,int>> q;
    int fresh = 0;
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < m; ++j) {
            if (g[i][j] == 2) q.push({i, j});          // all sources at distance 0
            else if (g[i][j] == 1) ++fresh;
        }
    const int dr[4] = {1, -1, 0, 0}, dc[4] = {0, 0, 1, -1};
    int minutes = 0;
    while (!q.empty() && fresh > 0) {
        int layer = q.size();                          // process exactly one layer
        for (int k = 0; k < layer; ++k) {
            auto [r, c] = q.front(); q.pop();
            for (int d = 0; d < 4; ++d) {
                int nr = r + dr[d], nc = c + dc[d];
                if (nr < 0 || nr >= n || nc < 0 || nc >= m || g[nr][nc] != 1) continue;
                g[nr][nc] = 2;                         // mark visited WHEN ENQUEUED
                --fresh;
                q.push({nr, nc});
            }
        }
        ++minutes;
    }
    return fresh == 0 ? minutes : -1;
}

